window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b18c4d2d41b1fb41"]={"versions": [{"id": "FIG-b18c4d2d41b1fb41", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram).</li>\n<li><strong>Architektonische Einordnung:</strong> AUTOSAR Classic Platform, BSW-Schicht, Sub-Modul <em>E2E Transformer</em> (<code>E2EXf</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Spezifikation der internen Kontrollfluss-Logik für die Sub-Aktivität <code>E2EXf_Inv_store_request_counter</code>. Sie dient der serverseitigen Extraktion und Zwischenspeicherung des Request-Zählers (<code>receivedRequestCounter</code>) aus dem E2E-Prüfzustand während der Abarbeitung eines Client-Server-Aufrufs im inversen Transformer (<code>E2EXf_Inv_&lt;TransformerId&gt;</code>). Dieser Wert ist Voraussetzung für die Request-Response-Korrelation und die Absicherung gegen Antwortvertauschung (RS_E2E_08538).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontrollfluss-Elemente:</strong></li>\n<li><em>Initial Node</em> (Startknoten) & <em>Activity Final Node</em> (Endknoten).</li>\n<li><em>Decision Node</em> (Verzweigungsraute) mit Guard-Condition: <code>Profile == 01 || Profile == 02</code>.</li>\n<li><em>Merge Node</em> (Zusammenführungsraute) zur Zusammenführung beider Kontrollpfade.</li>\n<li>Zwei <em>Action Nodes</em> vom Stereotyp <code>WriteVariable</code>.</li>\n<li><strong>Datenstrukturen & Variablen:</strong></li>\n<li><code>Profile</code>: Konfiguriertes E2E-Schutzprofil (z. B. E2E Profile 01, 02, 04, 05, 07, 11, 22).</li>\n<li><code>state</code>: Zeiger auf die profilspezifische Check-State-Struktur der E2E-Library (z. B. <code>E2E_P01CheckStateType</code>, <code>E2E_P04CheckStateType</code>).</li>\n<li><code>state-&gt;LastValidCounter</code>: Profil 01/02-spezifisches Zustandsfeld, das den Zählerstand der zuletzt als gültig bewerteten Nachricht hält.</li>\n<li><code>state-&gt;Counter</code>: Zustandsfeld aller übrigen E2E-Profile, welches den aktuell extrahierten Zähler der empfangenen Botschaft abbildet.</li>\n<li><code>receivedRequestCounter</code>: Interne Zustands- bzw. Kontextvariable des inversen Transformers zur Pufferung des Zählers für die korrespondierende Response-Generierung.</li>\n<li><strong>Traceability / Annotation:</strong></li>\n<li>Kommentar-Knoten mit Verknüpfung zu den normativen Spezifikationsanforderungen <code>[SWS_E2EXf_00206]</code> und <code>[SWS_E2EXf_00207]</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität wird synchron innerhalb von <code>E2EXf_Inv_&lt;TransformerId&gt;</code> unmittelbar nach erfolgreicher Ausführung von <code>E2E_P&lt;xx&gt;Check()</code> durchlaufen:</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Kontrollfluss startet am Initial Node.</li>\n<li><strong>Profilabfrage (Decision Node):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad <code>[TRUE]</code> (E2E Profile 01 oder 02):</strong></li>\n<li>Ausführung der Aktion <code>WriteVariable</code>: Zuweisung <code>receivedRequestCounter = state-&gt;LastValidCounter</code> (SWS_E2EXf_00206).</li>\n<li><strong>Pfad <code>[FALSE]</code> (alle anderen Profile, z. B. Profile 04, 05, 06, 07, 11, 22):</strong></li>\n<li>Ausführung der Aktion <code>WriteVariable</code>: Zuweisung <code>receivedRequestCounter = state-&gt;Counter</code> (SWS_E2EXf_00207).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zusammenführung & Abschluss:</strong> Zusammenführung im Merge Node und reguläre Beendigung am Activity Final Node.</li>\n<li><strong>Fehlerpfade/Abbrüche:</strong> Keine Verzweigung bei E2E-Check-Fehlern innerhalb dieses Diagramms; die Aktivität setzt voraus, dass die Botschaft zuvor die primäre E2E-Plausibilisierung durchlaufen hat.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW- & Code-Generator-Implementierung:</strong></li>\n<li><em>Heterogene Datenstrukturen der E2E-Library:</em> In Profile 01 (<code>E2E_P01Check</code>) und Profile 02 (<code>E2E_P02Check</code>) repräsentiert <code>state-&gt;Counter</code> den intern hochgezählten Erwartungszähler/Deltawert, weshalb zwingend <code>LastValidCounter</code> für den tatsächlichen Wert der aktuellen Nachricht ausgelesen werden muss. Neuere Profile vereinheitlichen dies direkt in <code>state-&gt;Counter</code>.</li>\n<li>Der BSW-Code-Generator muss diesen Pfadunterschied zwingend statisch zur Compile-Zeit optimieren bzw. polymorph im serialisierten Transformer-Code auflösen.</li>\n<li><strong>Client-Server-Bindung:</strong></li>\n<li>Gilt ausschließlich für Client-Server-Kommunikation (<code>isClientServer = TRUE</code>). Bei Sender-Receiver-Schnittstellen entfällt die Speicherung von <code>receivedRequestCounter</code>, da kein Antwort-Header erzeugt werden muss.</li>\n<li>Der gepufferte Zählerwert <code>receivedRequestCounter</code> muss vom RTE/Transformer-Kontext vorgehalten werden, bis die Server-Runnable das Ergebnis bereitstellt und der vorwärtsgerichtete Response-Transformer (<code>E2EXf_&lt;TransformerId&gt;</code>) den Zähler in den E2E-Header der Antwort einbettet (Schutz gegen Replay/Out-of-Order Responses gem. SWS_E2EXf_00165).</li>\n</ul>"}, {"id": "FIG-146be95819c57124", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram).</li>\n<li><strong>Architektonische Einordnung:</strong> AUTOSAR Classic Platform, BSW-Schicht, Sub-Modul <em>E2E Transformer</em> (<code>E2EXf</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Spezifikation der internen Kontrollfluss-Logik für die Sub-Aktivität <code>E2EXf_Inv_store_request_counter</code>. Sie dient der serverseitigen Extraktion und Zwischenspeicherung des Request-Zählers (<code>receivedRequestCounter</code>) aus dem E2E-Prüfzustand während der Abarbeitung eines Client-Server-Aufrufs im inversen Transformer (<code>E2EXf_Inv_&lt;TransformerId&gt;</code>). Dieser Wert ist Voraussetzung für die Request-Response-Korrelation und die Absicherung gegen Antwortvertauschung (RS_E2E_08538).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontrollfluss-Elemente:</strong></li>\n<li><em>Initial Node</em> (Startknoten) & <em>Activity Final Node</em> (Endknoten).</li>\n<li><em>Decision Node</em> (Verzweigungsraute) mit Guard-Condition: <code>Profile == 01 || Profile == 02</code>.</li>\n<li><em>Merge Node</em> (Zusammenführungsraute) zur Zusammenführung beider Kontrollpfade.</li>\n<li>Zwei <em>Action Nodes</em> vom Stereotyp <code>WriteVariable</code>, farblich als <code>C/S: Server</code> gekennzeichnet.</li>\n<li><strong>Visuelle Syntax / Legende:</strong></li>\n<li>Farblegende <code>Communication Types</code> zur Unterscheidung der Kommunikationsarten (<code>All types</code>, <code>Sender/Receiver</code>, <code>Publisher/Subscriber</code>, <code>C/S: Server</code>, <code>C/S: Client</code>, <code>Signal to Service</code>).</li>\n<li><strong>Datenstrukturen & Variablen:</strong></li>\n<li><code>Profile</code>: Konfiguriertes E2E-Schutzprofil (z. B. E2E Profile 01, 02, 04, 05, 07, 11, 22).</li>\n<li><code>state</code>: Zeiger auf die profilspezifische Check-State-Struktur der E2E-Library (z. B. <code>E2E_P01CheckStateType</code>, <code>E2E_P04CheckStateType</code>).</li>\n<li><code>state-&gt;LastValidCounter</code>: Profil 01/02-spezifisches Zustandsfeld, das den Zählerstand der zuletzt als gültig bewerteten Nachricht hält.</li>\n<li><code>state-&gt;Counter</code>: Zustandsfeld aller übrigen E2E-Profile, welches den aktuell extrahierten Zähler der empfangenen Botschaft abbildet.</li>\n<li><code>receivedRequestCounter</code>: Interne Zustands- bzw. Kontextvariable des inversen Transformers zur Pufferung des Zählers für die korrespondierende Response-Generierung.</li>\n<li><strong>Traceability / Annotation:</strong></li>\n<li>Kommentar-Knoten mit Verknüpfung zu den normativen Spezifikationsanforderungen <code>[SWS_E2EXf_00165]</code> und <code>[SWS_E2EXf_00166]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität wird synchron innerhalb von <code>E2EXf_Inv_&lt;TransformerId&gt;</code> unmittelbar nach erfolgreicher Ausführung von <code>E2E_P&lt;xx&gt;Check()</code> durchlaufen:</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Kontrollfluss startet am Initial Node.</li>\n<li><strong>Profilabfrage (Decision Node):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad <code>[TRUE]</code> (E2E Profile 01 oder 02):</strong></li>\n<li>Ausführung der Aktion <code>WriteVariable</code>: Zuweisung <code>receivedRequestCounter = state-&gt;LastValidCounter</code> (SWS_E2EXf_00165).</li>\n<li><strong>Pfad <code>[FALSE]</code> (alle anderen Profile, z. B. Profile 04, 05, 06, 07, 11, 22):</strong></li>\n<li>Ausführung der Aktion <code>WriteVariable</code>: Zuweisung <code>receivedRequestCounter = state-&gt;Counter</code> (SWS_E2EXf_00166).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zusammenführung & Abschluss:</strong> Zusammenführung im Merge Node und reguläre Beendigung am Activity Final Node.</li>\n<li><strong>Fehlerpfade/Abbrüche:</strong> Keine Verzweigung bei E2E-Check-Fehlern innerhalb dieses Diagramms; die Aktivität setzt voraus, dass die Botschaft zuvor die primäre E2E-Plausibilisierung durchlaufen hat.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW- & Code-Generator-Implementierung:</strong></li>\n<li><em>Heterogene Datenstrukturen der E2E-Library:</em> In Profile 01 (<code>E2E_P01Check</code>) und Profile 02 (<code>E2E_P02Check</code>) repräsentiert <code>state-&gt;Counter</code> den intern hochgezählten Erwartungszähler/Deltawert, weshalb zwingend <code>LastValidCounter</code> für den tatsächlichen Wert der aktuellen Nachricht ausgelesen werden muss. Neuere Profile vereinheitlichen dies direkt in <code>state-&gt;Counter</code>.</li>\n<li>Der BSW-Code-Generator muss diesen Pfadunterschied zwingend statisch zur Compile-Zeit optimieren bzw. polymorph im serialisierten Transformer-Code auflösen.</li>\n<li><strong>Client-Server-Bindung:</strong></li>\n<li>Gilt ausschließlich für Client-Server-Kommunikation (<code>isClientServer = TRUE</code>). Bei Sender-Receiver-Schnittstellen entfällt die Speicherung von <code>receivedRequestCounter</code>, da kein Antwort-Header erzeugt werden muss.</li>\n<li>Der gepufferte Zählerwert <code>receivedRequestCounter</code> muss vom RTE/Transformer-Kontext vorgehalten werden, bis die Server-Runnable das Ergebnis bereitstellt und der vorwärtsgerichtete Response-Transformer (<code>E2EXf_&lt;TransformerId&gt;</code>) den Zähler in den E2E-Header der Antwort einbettet (Schutz gegen Replay/Out-of-Order Responses gem. SWS_E2EXf_00165).</li>\n</ul>"}, {"id": "FIG-7d83eb6c715a08f7", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram).</li>\n<li><strong>Architektonische Einordnung:</strong> AUTOSAR Classic Platform, BSW-Schicht, Sub-Modul <em>E2E Transformer</em> (<code>E2EXf</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Spezifikation der internen Kontrollfluss-Logik für die Sub-Aktivität <code>E2EXf_Inv_store_request_counter</code>. Sie dient der serverseitigen Extraktion und Zwischenspeicherung des Request-Zählers (<code>receivedRequestCounter</code>) aus dem E2E-Prüfzustand während der Abarbeitung eines Client-Server-Aufrufs im inversen Transformer (<code>E2EXf_Inv_&lt;TransformerId&gt;</code>). Dieser Wert ist Voraussetzung für die Request-Response-Korrelation und die Absicherung gegen Antwortvertauschung (RS_E2E_08538).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontrollfluss-Elemente:</strong></li>\n<li><em>Initial Node</em> (Startknoten) & <em>Activity Final Node</em> (Endknoten).</li>\n<li><em>Decision Node</em> (Verzweigungsraute) mit Guard-Condition: <code>Profile == 01 || Profile == 02</code>.</li>\n<li><em>Merge Node</em> (Zusammenführungsraute) zur Zusammenführung beider Kontrollpfade.</li>\n<li>Zwei <em>Action Nodes</em> vom Stereotyp <code>WriteVariable</code>, farblich als <code>C/S: Server</code> gekennzeichnet.</li>\n<li><strong>Visuelle Syntax / Legende:</strong></li>\n<li>Farblegende <code>Legend</code> zur Unterscheidung der Kommunikationsarten (<code>All types</code>, <code>Sender/Receiver</code>, <code>Publisher/Subscriber</code>, <code>C/S: Server</code>, <code>C/S: Client</code>, <code>Signal to Service</code>).</li>\n<li><strong>Datenstrukturen & Variablen:</strong></li>\n<li><code>Profile</code>: Konfiguriertes E2E-Schutzprofil (z. B. E2E Profile 01, 02, 04, 05, 07, 11, 22).</li>\n<li><code>state</code>: Zeiger auf die profilspezifische Check-State-Struktur der E2E-Library (z. B. <code>E2E_P01CheckStateType</code>, <code>E2E_P04CheckStateType</code>).</li>\n<li><code>state-&gt;LastValidCounter</code>: Profil 01/02-spezifisches Zustandsfeld, das den Zählerstand der zuletzt als gültig bewerteten Nachricht hält.</li>\n<li><code>state-&gt;Counter</code>: Zustandsfeld aller übrigen E2E-Profile, welches den aktuell extrahierten Zähler der empfangenen Botschaft abbildet.</li>\n<li><code>receivedRequestCounter</code>: Interne Zustands- bzw. Kontextvariable des inversen Transformers zur Pufferung des Zählers für die korrespondierende Response-Generierung.</li>\n<li><strong>Traceability / Annotation:</strong></li>\n<li>Kommentar-Knoten mit Verknüpfung zu den normativen Spezifikationsanforderungen <code>[SWS_E2EXf_00165]</code> und <code>[SWS_E2EXf_00166]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität wird synchron innerhalb von <code>E2EXf_Inv_&lt;TransformerId&gt;</code> unmittelbar nach erfolgreicher Ausführung von <code>E2E_P&lt;xx&gt;Check()</code> durchlaufen:</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Kontrollfluss startet am Initial Node.</li>\n<li><strong>Profilabfrage (Decision Node):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad <code>[TRUE]</code> (E2E Profile 01 oder 02):</strong></li>\n<li>Ausführung der Aktion <code>WriteVariable</code>: Zuweisung <code>receivedRequestCounter = state-&gt;LastValidCounter</code> (SWS_E2EXf_00165).</li>\n<li><strong>Pfad <code>[FALSE]</code> (alle anderen Profile, z. B. Profile 04, 05, 06, 07, 11, 22):</strong></li>\n<li>Ausführung der Aktion <code>WriteVariable</code>: Zuweisung <code>receivedRequestCounter = state-&gt;Counter</code> (SWS_E2EXf_00166).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zusammenführung & Abschluss:</strong> Zusammenführung im Merge Node und reguläre Beendigung am Activity Final Node.</li>\n<li><strong>Fehlerpfade/Abbrüche:</strong> Keine Verzweigung bei E2E-Check-Fehlern innerhalb dieses Diagramms; die Aktivität setzt voraus, dass die Botschaft zuvor die primäre E2E-Plausibilisierung durchlaufen hat.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW- & Code-Generator-Implementierung:</strong></li>\n<li><em>Heterogene Datenstrukturen der E2E-Library:</em> In Profile 01 (<code>E2E_P01Check</code>) und Profile 02 (<code>E2E_P02Check</code>) repräsentiert <code>state-&gt;Counter</code> den intern hochgezählten Erwartungszähler/Deltawert, weshalb zwingend <code>LastValidCounter</code> für den tatsächlichen Wert der aktuellen Nachricht ausgelesen werden muss. Neuere Profile vereinheitlichen dies direkt in <code>state-&gt;Counter</code>.</li>\n<li>Der BSW-Code-Generator muss diesen Pfadunterschied zwingend statisch zur Compile-Zeit optimieren bzw. polymorph im serialisierten Transformer-Code auflösen.</li>\n<li><strong>Client-Server-Bindung:</strong></li>\n<li>Gilt ausschließlich für Client-Server-Kommunikation (<code>isClientServer = TRUE</code>). Bei Sender-Receiver-Schnittstellen entfällt die Speicherung von <code>receivedRequestCounter</code>, da kein Antwort-Header erzeugt werden muss.</li>\n<li>Der gepufferte Zählerwert <code>receivedRequestCounter</code> muss vom RTE/Transformer-Kontext vorgehalten werden, bis die Server-Runnable das Ergebnis bereitstellt und der vorwärtsgerichtete Response-Transformer (<code>E2EXf_&lt;TransformerId&gt;</code>) den Zähler in den E2E-Header der Antwort einbettet (Schutz gegen Replay/Out-of-Order Responses gem. SWS_E2EXf_00165).</li>\n</ul>"}], "trans": [{"from": "FIG-b18c4d2d41b1fb41", "to": "FIG-146be95819c57124", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Farblegende hinzugefügt:</strong> Neuer Legendenkasten „Communication Types“ oben links zur Kennzeichnung von Kommunikationsarten (<code>All types</code>, <code>Sender/Receiver</code>, <code>Publisher/Subscriber</code>, <code>C/S: Server</code>, <code>C/S: Client</code>, <code>Signal to Service</code>).</li>\n<li><strong>Farbcodierung der Aktionen:</strong> Die beiden Action Nodes <code>WriteVariable</code> sind nun türkis/cyan eingefärbt und damit gemäß Legende der Kommunikationsart <code>C/S: Server</code> zugeordnet.</li>\n<li><strong>Traceability / Annotation:</strong> Der Kommentar-Knoten referenziert nun <code>[SWS_E2EXf_00165]</code> und <code>[SWS_E2EXf_00166]</code> (zuvor <code>[SWS_E2EXf_00206]</code> und <code>[SWS_E2EXf_00207]</code>) und wurde von unten links zentral zwischen die beiden Kontrollflusszweige verlegt.</li>\n</ul>"}, {"from": "FIG-146be95819c57124", "to": "FIG-7d83eb6c715a08f7", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Legende:</strong> Titel des Legendenkastens von „Communication Types“ in „Legend“ umbenannt.</li>\n</ul>"}]};
